class Solution {
public:
    TreeNode* str2tree(string s) {
        if (s.empty()) return nullptr;
        size_t firstParen = s.find('(');
        if (firstParen == string::npos) {
            return new TreeNode(stoi(s));
        }
        TreeNode* root = new TreeNode(stoi(s.substr(0, firstParen)));
        int start = firstParen;
        int balance = 0;
        for (int i = firstParen; i < (int)s.size(); i++) {
            if (s[i] == '(') balance++;
            else if (s[i] == ')') balance--;
            if (balance == 0) {
                if (!root->left) {
                    root->left = str2tree(s.substr(start + 1, i - start - 1));
                    start = i + 1;
                } else {
                    root->right = str2tree(s.substr(start + 1, i - start - 1));
                }
            }
        }
        return root;
    }
};

class Solution {
    public TreeNode str2tree(String s) {
        if (s == null || s.isEmpty()) return null;
        int firstParen = s.indexOf('(');
        if (firstParen == -1) {
            return new TreeNode(Integer.parseInt(s));
        }
        TreeNode root = new TreeNode(Integer.parseInt(s.substring(0, firstParen)));
        int start = firstParen;
        int balance = 0;
        for (int i = firstParen; i < s.length(); i++) {
            if (s.charAt(i) == '(') balance++;
            else if (s.charAt(i) == ')') balance--;
            if (balance == 0) {
                if (root.left == null) {
                    root.left = str2tree(s.substring(start + 1, i));
                    start = i + 1;
                } else {
                    root.right = str2tree(s.substring(start + 1, i));
                }
            }
        }
        return root;
    }
}

var str2tree = function(s) {
    if (!s || s.length === 0) return null;
    const firstParen = s.indexOf("(");
    if (firstParen === -1) {
        return new TreeNode(parseInt(s, 10));
    }
    const root = new TreeNode(parseInt(s.slice(0, firstParen), 10));
    let start = firstParen;
    let balance = 0;
    for (let i = firstParen; i < s.length; i++) {
        if (s[i] === "(") balance++;
        else if (s[i] === ")") balance--;
        if (balance === 0) {
            if (!root.left) {
                root.left = str2tree(s.slice(start + 1, i));
                start = i + 1;
            } else {
                root.right = str2tree(s.slice(start + 1, i));
            }
        }
    }
    return root;
